-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhCN" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.paladin.holy.Name"] = "神圣"
L["rm.era.paladin.holy.Description"] = "使用神圣天赋树在队伍中治疗，10 级起。作用于你的友方目标，并按损失的生命值选择治疗法术：清洁术或纯净术，移动时使用神圣震击，低于 40% 时使用最高等级圣光术，低于 65% 时使用 6 级圣光术，低于 85% 时使用最高等级圣光闪现，低于 95% 时使用 4 级圣光闪现。近战范围内有敌人时：智慧圣印，团队副本之外还会使用审判。提醒：专注光环或虔诚光环、智慧祝福，目标生命值极低时使用神恩术和圣疗术。治疗谁由你自己掌控；单刷的神圣圣骑士会改用惩戒内置循环。"
L["rm.era.paladin.protection.Name"] = "防护"
L["rm.era.paladin.protection.Description"] = "坦克循环，适用于 1 至 60 级，开启正义之怒或使用防护天赋树时选用。正义圣印（法力值低于 40% 时用智慧圣印），以神圣之盾和审判拉怪，保持神圣之盾，有两个或更多敌人攻击你时使用奉献和神圣愤怒（亡灵和恶魔），否则施放一次十字军审判，然后在法力有余时使用审判和奉献，对亡灵和恶魔使用驱邪术。提醒：正义之怒、虔诚光环、庇护祝福、王者祝福或力量祝福，濒死时使用圣疗术。嘲讽、反复施放王者祝福和法术等级由你自己掌控。"
L["rm.era.paladin.protection.icyveins.Name"] = "防护，智慧圣印（Icy Veins）"
L["rm.era.paladin.protection.icyveins.Description"] = "Icy Veins 的团队坦克循环，搭配 Wowhead 的智慧轮换，是推荐的防护内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。保持智慧圣印，目标没有智慧审判时就审判它，否则只用审判拉怪；神圣之盾，奉献冷却完毕即用，对亡灵和恶魔怪群使用神圣愤怒，驱邪术，团队中以强效王者祝福作为仇恨填充。提醒与推荐的内置循环相同。"
L["rm.era.paladin.retribution.Name"] = "惩戒"
L["rm.era.paladin.retribution.Description"] = "惩戒近战，适用于 1 至 60 级，也是没有其他内置循环适用时所有圣骑士的默认循环。在团队副本之外面对精英和长时间战斗时，施放十字军圣印并审判一次；否则保持一个圣印（武器速度为 3.5 秒或更慢时用命令圣印，否则用正义圣印），对亡灵和恶魔使用驱邪术和神圣愤怒，愤怒之锤，审判冷却完毕即用，复仇生效时或有两个或更多近身敌人时使用奉献。提醒：圣洁光环、惩罚光环或虔诚光环，单刷时用智慧祝福、组队时用力量祝福，战斗间隙的治疗，即将死亡时使用圣盾术、圣佑术或圣疗术。圣印轮换是单独的内置循环；目标选择和站位由你自己掌控。"
L["rm.era.paladin.retribution.twist.Name"] = "惩戒，圣印轮换"
L["rm.era.paladin.retribution.twist.Description"] = "默认关闭；如果你会进行圣印轮换，请启用它。适用于拥有命令圣印的惩戒圣骑士：保持正义圣印，在挥击前的最后 0.4 秒切换为 1 级命令圣印，然后再切换回来，审判一就绪就使用，对亡灵和恶魔使用驱邪术和神圣愤怒，愤怒之锤，复仇生效时使用奉献。需要大量法力值和良好的时机掌握。提醒与惩戒内置循环相同。"
L["rm.forever.paladin.holy.Name"] = "神圣"
L["rm.forever.paladin.holy.Description"] = "当神圣是你的主要天赋树且已点出 21 点（神圣震击所在层）并且正义之怒未开启时的团队治疗（组队的震击骑也会使用这里）。治疗你当前的友方目标：对带有你的圣光守望的目标使用神圣震击，战斗中使用圣光守望，清洁术或纯净术，移动时使用神圣震击，圣光灌注触发时使用圣光术，圣光闪现作为主要治疗。目标为敌人时：有光明圣印时使用圣光审判，神圣震击，圣光守望，神圣打击，驱邪术。提醒：没有圣印时使用光明圣印、战斗中对友方目标使用神恩术、你的光环和祝福。在永久服上生命值和法力值对插件隐藏，因此你选中的目标是判断谁需要治疗的唯一依据；紧急神圣震击、大量治疗的圣光术和圣疗术由你自己决定。"
L["rm.forever.paladin.holy.wowhead.Name"] = "神圣，神圣震击冷却完毕即用（Wowhead）"
L["rm.forever.paladin.holy.wowhead.Description"] = "Wowhead 的治疗打法，是推荐的神圣内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。神圣震击作为常规治疗冷却完毕即用，驱散，圣光闪现（永久服中生命值是隐藏的，因此缺口较大时使用圣光术由你自己决定）。目标为敌人时，它会通过切换到光明圣印、审判，再切换回正义圣印来保持你的圣光审判，然后是神圣打击、对亡灵和恶魔使用驱邪术、神圣震击和奉献。提醒与神圣内置循环相同。"
L["rm.forever.paladin.protection.Name"] = "防护（Wowhead）"
L["rm.forever.paladin.protection.Description"] = "当防护是你的主要天赋树，或你开启正义之怒后的坦克循环。目标正在攻击其他人时：配合愤怒圣印使用审判（嘲讽），用迅捷审判重置它。与两个或更多敌人交战时：奉献，对亡灵和恶魔使用驱邪术和神圣愤怒，神圣打击。单个敌人时：对亡灵和恶魔使用驱邪术，神圣打击，奉献。提醒：正义之怒、愤怒圣印、审判冷却完毕即用、坦克时的神圣之盾、你的光环和祝福。在永久服上生命值和法力值对插件隐藏，因此圣殿骑士壁垒和圣疗术由你自己决定。拉怪、站位和其他嘲讽由你自己掌控。"
L["rm.forever.paladin.protection.icyveins.Name"] = "防护，奉献优先（Icy Veins）"
L["rm.forever.paladin.protection.icyveins.Description"] = "Icy Veins 的坦克打法，是推荐的 Wowhead 防护内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。只要负担得起就优先奉献，单个敌人时也一样；审判留作嘲讽使用（没有冷却完毕即用的提醒），用迅捷审判重置它；然后是神圣打击，对亡灵和恶魔使用驱邪术。其余坦克提醒相同。"
L["rm.forever.paladin.retribution.Name"] = "惩戒"
L["rm.forever.paladin.retribution.Description"] = "适用于 1 至 60 级的惩戒及所有近战圣骑士，也是永久服圣骑士的默认循环。保持一个伤害圣印，仅在即将消失时刷新：对精英目标审判一次十字军圣印，然后使用慢速（3.0 秒）武器时用命令圣印，否则用正义圣印。然后神圣打击冷却完毕即用，震击骑（Shockadin）使用神圣震击和圣光守望，对亡灵和恶魔使用驱邪术，三个或更多敌人时使用奉献，可施放时使用愤怒之锤，以及近战。审判不受公共冷却影响，因此只要有圣印，它就作为提醒出现。其他提醒：你的光环和祝福（学会后为惩罚光环和王者祝福；会保留你自己选择的）。默认关闭的可选步骤：命令圣印审判前使用制裁之锤。在永久服上法力值、生命值和挥击计时对插件隐藏，因此节省法力、治疗自己、圣疗术和圣光扭转圣印切换由你自己决定。基于 30 级测试版指南制作。"
L["rm.mop.paladin.holy.Name"] = "推荐"
L["rm.mop.paladin.holy.Description"] = "适用于神圣专精，10 级起在神圣专精中选用。选中友方时进行治疗：3 点神圣能量（或神圣意志）时，你附近有三人受伤则使用黎明圣光，否则对没有永恒之火的目标施放永恒之火，再否则使用荣耀圣令；神圣震击冷却完毕即用；圣光灌注用于圣光普照或神圣之光，三层无私治愈用于圣光普照或圣光闪现；低于 35% 时使用圣光闪现；队伍受伤时使用圣光普照；神圣之光，然后用圣光术补满。选中敌人时造成伤害：神圣震击、审判、十字军打击、神圣棱镜、处决宣判、愤怒之锤、谴责。提醒：另一个圣印（正义圣印除外）生效或没有圣印时使用洞察圣印、祝福、责难、对你的焦点目标施放圣光道标和圣洁护盾（请将坦克设为焦点目标）、法力值低于 60% 时使用神圣恳求、三人低于 70% 时使用圣光之锤和你的治疗冷却技能、对濒死目标使用圣疗术。治疗谁、驱散和鼠标悬停治疗由你自己掌控。"
L["rm.mop.paladin.protection.Name"] = "推荐"
L["rm.mop.paladin.protection.Description"] = "推荐防护专精使用，10 级起在防护专精中选用。以复仇者之盾拉怪，然后大十字军触发时使用复仇者之盾，复仇者之盾，愤怒之锤，十字军打击，审判，你的 90 级天赋，奉献，神圣愤怒和圣洁护盾。有三个或更多敌人攻击你时改为复仇者之盾、奉献、正义之锤、审判和神圣愤怒。正义盾击、永恒之火和荣耀圣令不占用公共冷却，因此会在循环之外单独亮起：只要负担得起就使用正义盾击，有 3 点神圣能量和三层荣耀堡垒时，在永恒之火即将结束时对自己施放，没有该天赋时生命值低于一半使用荣耀圣令。其他提醒：正义之怒、另一个圣印（正义圣印除外）生效或没有圣印时使用洞察圣印、祝福、责难、圣洁护盾、坦克期间使用复仇之怒和神圣复仇者，以及根据你的生命值使用远古列王守卫、炽热防御者、圣佑术和圣疗术。它无法看到即将到来的伤害，因此大型防御技能请自行规划。"
L["rm.mop.paladin.protection.simulator.Name"] = "攒神圣能量（模拟器）"
L["rm.mop.paladin.protection.simulator.Description"] = "作为推荐防护内置循环的替代，默认关闭：启用它并禁用那个，或提高它的优先级。遵循模拟器的坦克列表：正义盾击会等到神圣能量满，除非你的生命值低于 40% 或神圣意志让它免费；荣耀堡垒超过两层时，在永恒之火即将消失前施放；保持圣洁护盾；神圣复仇者和复仇之怒冷却完毕即用。能量生成技能依次为十字军打击、审判，然后是复仇者之盾、神圣愤怒、90 级天赋和愤怒之锤，三个敌人时的范围伤害顺序相同。配合首领时机的防御技能由你掌控。"
L["rm.mop.paladin.retribution.Name"] = "推荐"
L["rm.mop.paladin.retribution.Description"] = "推荐惩戒专精使用，10 级起在惩戒专精中选用。保持异端裁决（3 点神圣能量时施放，在最后 3 秒内刷新；81 级起），在产生更多神圣能量前，于神圣能量满或免费触发时使用圣殿骑士的裁决，然后是愤怒之锤、十字军打击、审判和驱邪术，没有其他技能就绪时在 3 点时使用圣殿骑士的裁决。复仇之怒期间立即消耗，并把审判排在十字军打击之前。有两个或更多敌人攻击你时改用神圣风暴，四个敌人靠近时加上正义之锤。从远处用审判或驱邪术拉怪，单刷且处境危险时建议使用荣耀圣令。提醒：另一个圣印生效或没有圣印时施放真理圣印（会保留正义圣印）、王者祝福或力量祝福、责难、对精英在异端裁决生效时使用复仇之怒和远古列王守卫、复仇之怒期间使用神圣复仇者、处决宣判和圣光之锤，以及生命值低时使用圣佑术和圣疗术。对怪群使用正义圣印以及雕文选择由你自己掌控。"
L["rm.mop.paladin.retribution.warcrafttavern.Name"] = "驱邪术优先（Warcraft Tavern）"
L["rm.mop.paladin.retribution.warcrafttavern.Description"] = "作为推荐惩戒内置循环的替代，默认关闭：启用它并禁用那个，或提高它的优先级。每次冷却完毕和战争艺术重置时的驱邪术优先；异端裁决缺失时无论神圣能量多少都施放，并在最后 20 秒内于 3 点时刷新；然后是十字军打击、审判、圣殿骑士的裁决和愤怒之锤（拥有圣洁怒火时在复仇之怒期间优先）。两个或更多敌人时使用十字军打击、圣光之锤、审判、神圣风暴和愤怒之锤。复仇之怒和远古列王守卫仅对精英建议使用。指南中遇到任何顺劈情况就用正义圣印的做法交给你自己。"
L["rm.mop.paladin.unspecialized.Name"] = "选择专精前"
L["rm.mop.paladin.unspecialized.Description"] = "适用于 1 至 9 级，以及尚未选择专精的圣骑士；选择专精后由该专精的内置循环接管。从远处用审判拉怪，然后是十字军打击和审判，单刷且生命值低于一半时使用制裁之锤，低于 40% 时使用荣耀圣令。提醒：不在命令圣印时施放命令圣印（24 级起为真理圣印）、王者祝福、责难，以及脱战后受伤时使用圣光闪现。"
L["rm.retail.paladin.holy.Name"] = "Icy Veins"
L["rm.retail.paladin.holy.Description"] = "至暗之夜的神圣专精，仅供参考：Rotation Master 选择的是法术而不是目标，而且游戏在战斗中会隐藏所有人的生命值，因此它会针对你当前的目标让神圣能量和冷却技能持续运转，决定谁需要治疗则交给你。神圣能量在战斗中仍然可见，因此会优先在 5 点时消耗，并在你的其他治疗之后于 3 点或以上时消耗。友方目标：神圣能量达到 5 点时使用永恒之火或荣耀圣令，圣光灌注触发时使用圣光闪现，神圣震击，3 点或以上时使用永恒之火或荣耀圣令，圣光术，圣光闪现；黎明之光由你自己掌控。敌人：神圣能量达到 5 点时使用正义盾击，神圣震击，3 点或以上时使用正义盾击，审判，十字军打击，奉献。战斗中的提醒：圣洁鸣钟、神圣棱镜、神圣壁垒或圣洁武器、对友方目标使用美德道标、圣佑术；拉怪间隙的光环；责难。圣疗术由你自己掌控。复仇之怒和光环掌握由你自己掌控。"
L["rm.retail.paladin.initial.Name"] = "暴雪战斗辅助"
L["rm.retail.paladin.initial.Description"] = "推荐在你选择专精之前使用（此时游戏报告的是圣骑士的初始专精）。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时包含所有圣骑士内置循环共用的提醒，每一项在你学会对应法术后生效。当你在 10 级选择专精后，该专精的内置循环会接管。"
L["rm.retail.paladin.protection.Name"] = "暴雪战斗辅助"
L["rm.retail.paladin.protection.Description"] = "推荐至暗之夜的防护专精使用。显示暴雪的战斗辅助建议（已包含正义盾击、复仇之怒和戒卫），并在你施法或没有选中敌人时停止。提醒它未包含的内容：拉怪间隙的光环、对可打断的施法使用责难，以及战斗中一就绪就使用的炽热防御者和远古列王守卫。生命值在正式服中是隐藏的，因此何时使用它们以及圣疗术由你自己决定。嘲讽和站位仍由你自己掌控。"
L["rm.retail.paladin.protection.icyveins.Name"] = "参考（Icy Veins）"
L["rm.retail.paladin.protection.icyveins.Description"] = "仅供参考，默认关闭：Icy Veins 和 SimulationCraft 的施放顺序需要奉献、先锋和闪耀之光的增益效果，而至暗之夜会在战斗中隐藏它们。拉怪前使用奉献；然后是圣洁鸣钟，圣光之锤，没有站在奉献中时使用奉献，有先锋时使用复仇者之盾，神圣能量达到 3 点或以上时使用正义盾击，愤怒之锤，审判，祝福之锤或正义之锤，复仇者之盾，有闪耀之光时使用荣耀圣令，奉献。提醒：复仇之怒或戒卫、神圣壁垒、复仇之怒之外使用圣洁武器、防御技能、光环、责难。"
L["rm.retail.paladin.protection.wowhead.Name"] = "奉献填充参考（Wowhead）"
L["rm.retail.paladin.protection.wowhead.Description"] = "仅供参考，默认关闭：Wowhead 的坦克施放顺序。审判冷却好就用，正义盾击，复仇者之盾，神圣能量为 0 时使用圣洁鸣钟，祝福之锤或正义之锤，奉献仅作为填充。生命值在正式服中是隐藏的，因此生命值低于一半时的荣耀圣令由你自己决定。提醒与 Icy Veins 参考循环相同。"
L["rm.retail.paladin.retribution.Name"] = "暴雪战斗辅助"
L["rm.retail.paladin.retribution.Description"] = "推荐至暗之夜的惩戒专精使用。在战斗中，游戏现在会对插件隐藏增益效果、减益效果、冷却时间和生命值，因此它会在你的动作条上显示暴雪自己的战斗辅助建议（一键循环），并在你施法或没有选中敌人时停止。它还会提醒你那些建议从不涵盖的内容：拉怪间隙的光环、对可打断的施法使用责难，以及战斗中一就绪就使用的圣佑术。生命值在正式服中是隐藏的，因此何时使用圣佑术和圣疗术由你自己决定。饰品和种族技能仍由你自己掌控。"
L["rm.retail.paladin.retribution.icyveins.Name"] = "参考（Icy Veins）"
L["rm.retail.paladin.retribution.icyveins.Description"] = "仅供参考，默认关闭：Icy Veins 和 SimulationCraft 的施放顺序需要读取增益效果、充能和敌人数量，而至暗之夜会在战斗中隐藏这些信息，因此它无法在战斗中可靠运行。圣光之锤；神圣意志触发的免费神圣能量消耗技能；灰烬觉醒冷却期间神圣能量达到 5 点时使用消耗技能；灰烬觉醒；圣洁鸣钟；战争艺术触发时使用公正之剑；愤怒之锤充能溢出前使用愤怒之锤；神圣能量达到 3 点或以上时，两个或更多敌人（或有苍穹之力）时使用神圣风暴，否则使用最终审判；愤怒之锤；公正之剑；审判；圣殿骑士打击或十字军打击。神圣能量在战斗中仍然可见，因此这些消耗时机在战斗中有效。提醒：复仇之怒、灰烬觉醒就绪时使用处决宣判、光环、责难、防御技能。"
L["rm.sod.paladin.holy.Name"] = "神圣（探索赛季）"
L["rm.sod.paladin.holy.Description"] = "探索赛季的队伍治疗，铭刻了圣光道标、神圣之光或圣洁护盾，或使用神圣天赋树且没有十字军打击时选用。作用于你的友方目标：清洁术，移动时或低于 30% 时使用神圣震击，低于 60% 时使用神圣之光（法力值低于一半时用圣光术），低于 90% 时使用圣光闪现。近战范围内有敌人时只保持一个圣印。提醒：对缺少圣光道标和圣洁护盾的目标施放它们、专注光环或虔诚光环、智慧祝福，目标生命值极低时使用神恩术和圣疗术。它所依据的指南来自第 4 阶段；治疗谁由你自己掌控。"
L["rm.sod.paladin.holy.wowhead.Name"] = "神圣，圣光术优先（探索赛季，Wowhead）"
L["rm.sod.paladin.holy.wowhead.Description"] = "Wowhead 针对高暴击装备的第 4 阶段治疗顺序，是推荐的探索赛季神圣内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。低于 75% 时使用神圣之光或圣光术，然后是清洁术，缺口较小或移动时使用神圣震击，低于 95% 时使用圣光闪现。提醒与推荐的内置循环相同。"
L["rm.sod.paladin.protection.Name"] = "防护（探索赛季）"
L["rm.sod.paladin.protection.Description"] = "探索赛季的坦克循环，开启正义之怒、铭刻了正义之锤或正义盾击，或使用防护天赋树时选用。殉道圣印，以神圣之盾、复仇者之盾和驱邪术拉怪，保持神圣之盾；单个目标时正义之锤、正义盾击、驱邪术、复仇者之盾、审判、神圣风暴、奉献；有三个或更多敌人攻击你时正义之锤、复仇者之盾、奉献、正义盾击、驱邪术。提醒：正义之怒、拉怪前的神圣之盾、虔诚光环、庇护祝福或王者祝福、复仇之怒、低于 40% 时使用圣佑术、圣疗术，组队时你的目标攻击其他人时使用清算之手。"
L["rm.sod.paladin.protection.simulator.Name"] = "防护（探索赛季，模拟器）"
L["rm.sod.paladin.protection.simulator.Description"] = "模拟器 的坦克列表，是推荐的探索赛季防护内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。只要有圣印就审判，在圣印即将结束前续上，神圣之盾，复仇者之盾，正义之锤，驱邪术，最后是正义盾击。提醒与推荐的内置循环相同。"
L["rm.sod.paladin.retribution.Name"] = "惩戒（探索赛季）"
L["rm.sod.paladin.retribution.Description"] = "探索赛季的近战，适用于 1 至 60 级，也是该赛季所有圣骑士的默认循环。保持殉道圣印（学会前为正义圣印），以驱邪术开场，神圣能量达到三点时使用神圣风暴，然后按武器速度：使用速度为 3.3 秒或更慢的双手武器时，十字军打击、驱邪术、神圣风暴和审判；使用更快的武器时，仅在圣印即将结束时审判，然后是驱邪术、十字军打击和神圣风暴。法力充足或有三个近身敌人时使用奉献，对亡灵和恶魔使用神圣愤怒（铭刻了净化之力时对任何目标使用），法力有余时使用愤怒之锤（铭刻了强化愤怒之锤时始终使用）。符文在你铭刻后即会使用。提醒：圣洁光环、一个祝福、配合光环掌握使用复仇之怒、战斗间隙的治疗、即将死亡时使用圣盾术。"
L["rm.sod.paladin.retribution.icyveins.Name"] = "惩戒（探索赛季，Icy Veins 第 4 阶段）"
L["rm.sod.paladin.retribution.icyveins.Description"] = "Icy Veins 和 Warcraft Tavern 较早的第 4 阶段列表，也适合升级，作为推荐的探索赛季惩戒内置循环的替代，默认关闭：启用它并禁用那个，或提高它的优先级。对精英和长时间战斗施放一次十字军审判，殉道圣印，驱邪术、十字军打击、神圣风暴和审判冷却完毕即用，法力充足或有三个近身敌人时使用奉献，愤怒之锤。提醒与推荐的循环相同。"
L["rm.sod.paladin.retribution.stacking.Name"] = "惩戒，圣印叠加（探索赛季）"
L["rm.sod.paladin.retribution.stacking.Description"] = "默认关闭；拥有承印者之魂符文或能让圣印残留的六件套装时请启用它（Rotation Master 无法看到两者中的任何一个）。同时保持命令圣印和殉道圣印，神圣能量达到三点时使用神圣风暴，十字军打击，驱邪术，对亡灵和恶魔使用神圣愤怒（铭刻了净化之力时对任何目标使用），奉献，以及在两个圣印都存在时审判。"
L["rm.sod.paladin.retribution.twist.Name"] = "惩戒，圣印轮换（探索赛季）"
L["rm.sod.paladin.retribution.twist.Description"] = "默认关闭；如果你使用慢速双手武器进行圣印轮换，请启用它。在每次挥击前的最后 0.4 秒于殉道圣印和命令圣印之间切换，在此之前的 1.9 秒内不建议任何占用公共冷却的技能，在两个圣印同时残留时审判，并且每次挥击使用一个填充技能：神圣能量达到三点时使用神圣风暴，十字军打击，驱邪术。需要攻击计时器和练习。"
L["rm.sod.paladin.shockadin.Name"] = "震击骑（探索赛季，模拟器）"
L["rm.sod.paladin.shockadin.Description"] = "默认关闭；如果你使用神圣天赋树输出伤害，请启用它。它在以神圣为主要天赋树且铭刻了震惊与敬畏时适用。殉道圣印（否则正义圣印），在圣印即将结束时审判，用神圣震击保持日光或在神圣能量达到三点时使用，驱邪术和十字军打击。提醒与探索赛季惩戒内置循环相同。"
L["rm.tbc.paladin.holy.Name"] = "神圣（Icy Veins & Wowhead）"
L["rm.tbc.paladin.holy.Description"] = "神圣圣骑士在队伍中的治疗，作用于你的友方目标：目标濒死时使用圣疗术或神圣震击，清洁术（42 级前为纯净术），移动时使用神圣震击，承受大量伤害时使用圣光术，用 5 级圣光术保持圣光之赐，否则使用圣光闪现。目标为敌对时保持智慧审判。提醒：专注光环、智慧祝福、神启和神恩术。单刷的神圣圣骑士会改用惩戒内置循环。"
L["rm.tbc.paladin.holy.wowhead.Name"] = "神圣（Wowhead 坦克治疗）"
L["rm.tbc.paladin.holy.wowhead.Description"] = "Wowhead 的团队坦克治疗，是推荐的神圣内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。只要目标损失十分之一的生命值就使用圣光术，仅在缺口较小时使用圣光闪现；紧急处理、驱散、审判和提醒与综合版神圣内置循环相同。"
L["rm.tbc.paladin.protection.icyveins.Name"] = "防护（Icy Veins）"
L["rm.tbc.paladin.protection.icyveins.Description"] = "Icy Veins 的坦克循环，是推荐的 Wowhead 防护内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。没人维持十字军审判时施放它，正义圣印（怪群时用智慧圣印），奉献作为主要仇恨来源，审判、神圣之盾，然后复仇者之盾和愤怒之锤冷却完毕即用。提醒与 Wowhead 版本相同，但不含复仇之怒。"
L["rm.tbc.paladin.protection.wowhead.Name"] = "防护（Wowhead & 模拟器）"
L["rm.tbc.paladin.protection.wowhead.Description"] = "防护天赋树或任何开启正义之怒的圣骑士的坦克循环。以神圣之盾、复仇者之盾和审判拉怪；面对碾压目标（世界首领或比你高三级及以上）时先上神圣之盾；然后是奉献、对亡灵和恶魔使用驱邪术、审判、神圣之盾、对亡灵怪群使用神圣愤怒，除碾压目标外使用复仇者之盾。法力值不足时对怪群使用智慧圣印，否则使用正义圣印。提醒：正义之怒、虔诚光环、庇护祝福（或王者祝福、智慧祝福）、复仇之怒、圣疗术。嘲讽和切换目标由你自己掌控。"
L["rm.tbc.paladin.retribution.icyveins.Name"] = "惩戒（Icy Veins）"
L["rm.tbc.paladin.retribution.icyveins.Description"] = "Icy Veins 的惩戒，是推荐的 Wowhead 惩戒内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。每个目标施放一次十字军审判，正义圣印（仅在使用慢速武器时用命令圣印，学会后用鲜血圣印或殉难圣印），十字军打击、愤怒之锤和审判冷却完毕即用，两个或更多敌人时使用奉献，对亡灵和恶魔使用驱邪术，神圣系升级者使用神圣震击。提醒与 Wowhead 版本相同。"
L["rm.tbc.paladin.retribution.twist.Name"] = "惩戒圣印轮换"
L["rm.tbc.paladin.retribution.twist.Description"] = "默认关闭；如果你会进行圣印轮换（64 级以上，拥有命令圣印和鲜血圣印或殉难圣印），请启用它。以十字军审判开场，之后每次挥击都会提前施放命令圣印（等级 1），并在最后 0.4 秒切换到鲜血圣印或殉难圣印，两次轮换之间使用十字军打击，只审判鲜血圣印或殉难圣印，驱邪术和奉献仅作为填充，法力值低于 12% 时不再轮换，只保持鲜血圣印。需要可靠的攻击计时器；未考虑延迟。"
L["rm.tbc.paladin.retribution.wowhead.Name"] = "惩戒（Wowhead & 模拟器）"
L["rm.tbc.paladin.retribution.wowhead.Description"] = "惩戒近战，适用于 1 至 70 级，也是没有其他内置循环适用时所有圣骑士的默认循环。对每个目标以智慧审判（法力值低时）或十字军审判开场，保持你最好的圣印（鲜血圣印或殉难圣印、命令圣印，其次是正义圣印），使用十字军打击，只审判正义圣印、鲜血圣印或殉难圣印（对昏迷的目标则审判命令圣印），对亡灵和恶魔使用驱邪术，三个或更多敌人且法力充足时使用奉献。愤怒之锤由你决定（Wowhead 仅对逃跑的目标使用）。提醒：圣洁光环、惩罚光环或虔诚光环、对自己施放祝福、战斗后治疗、复仇之怒。圣印轮换是单独的内置循环。"
